    "adj_hero_title": "How do we describe a noun?",
    "adj_hero_desc": "Adjectives illuminate the noun, revealing its qualities, state, and character.",
    "adj_choose_label": "Choose an adjective to paint the child:",
    "adj_card_sulten_type": "Physiological state",
    "adj_card_sulten_desc": "The body's basic need for nourishment.",
    "adj_card_glad_type": "Emotional state",
    "adj_card_glad_desc": "Positive mental energy.",
    "adj_card_lille_type": "Physical dimension",
    "adj_card_lille_desc": "Bodily size and volume.",
    "adj_card_hurtig_type": "Dynamic pace",
    "adj_card_hurtig_desc": "Movement at high speed.",
    "adj_expl_box": "The adjective attaches directly in front of the noun and paints a specific picture. When we change the adjective, the child's state changes – but the action itself <em>({modalWord} spise)</em> remains the same.",
    "adj_agreement_pill": "🧲 Cognitive Agreement",
    "adj_agreement_title": "Why do adjectives decline?",
    "adj_agreement_desc": "The adjective adapts to the noun like a magnet. The ending depends on whether the bond is strong (definite) or weak (indefinite).",
    "adj_ctrl_form_legend": "1. Form & Strength of Bond:",
    "adj_ctrl_bestemt": "⚡ Definite (Strong bond: always -e)",
    "adj_ctrl_ubestemt": "⚪ Indefinite (Weak bond: gender decides)",
    "adj_ctrl_noun_legend": "2. Noun & Grammatical Gender:",
    "adj_ctrl_barn": "👶 Barn (et-word / neuter)",
    "adj_ctrl_bil": "🚗 Bil (en-word / common)",
    "adj_ctrl_stem_legend": "3. Adjective Stem:",
    "adj_status_strong": "⚡ <strong>STRONG BOND:</strong> The magnet pulls with maximum force! The ending locks firmly onto <strong>-e</strong> regardless of gender (<em>{phrase}</em>).",
    "adj_status_weak_et": "⚪ <strong>WEAK BOND:</strong> Looser connection. The ending is determined by the noun's gender: neuter (et-word) takes <strong>-t</strong> (<em>{phrase}</em>).",
    "adj_status_weak_en": "⚪ <strong>WEAK BOND:</strong> Looser connection. The ending is determined by the noun's gender: common gender (en-word) takes <strong>-ø</strong> (no ending) (<em>{phrase}</em>).",
    "adj_box_adj_label": "Adjective",
    "adj_box_noun_label": "Noun (Magnet)",
    "adj_badge_strong": "⚡ STRONG BOND ⚡",
    "adj_badge_weak": "⚪ WEAK BOND ⚪",
    "adj_subrole_strong_barn": "Det barn (definite)",
    "adj_subrole_strong_bil": "Den bil (definite)",
    "adj_subrole_weak_barn": "Et barn (neuter)",
    "adj_subrole_weak_bil": "En bil (common gender)",
    "adj_syntese_strong": "⚡ Strong bond (-e):",
    "adj_syntese_weak": "⚪ Weak bond:",
    "adj_rule_strong": "<strong>Cognitive rule for strong agreement:</strong> When referring to a <em>definite</em> entity (\"det store barn\", \"den hurtige bil\"), the reference is already fixed. Therefore, Danish uses the fixed ending <strong>-e</strong> on the adjective – regardless of common or neuter gender.",
    "adj_rule_weak": "<strong>Cognitive rule for weak agreement:</strong> When the entity is <em>indefinite</em> (\"et stort barn\", \"en hurtig bil\"), the reference is open. Here, the adjective must reflect the grammatical gender: <strong>-t</strong> for et-words (neuter) and <strong>-ø</strong> (no ending) for en-words (common gender).",
    "adj_action_next_title": "Ready for the next step: Add Adverbs",
    "adj_action_next_desc": "Bring the sentence <strong>\"{sentence}\"</strong> along and learn how adverbs describe the very manner in which the child eats.",
    "adj_btn_next_adv": "Continue to Adverbs ➔",
    "adj_ordstilling_title": "Adjectives & Noun Phrases (Part 4)",
    "adj_ordstilling_desc": "Learn how adjectives and expanded noun phrases are positioned in the sentence schema.",
    "adj_ordstilling_btn": "Go to Word Order (Part 4) ➔",
    "adv_hero_title": "How do we describe an action?",
    "adv_hero_subtitle": "Where adjectives paint the <strong>thing</strong> (<em>det {adj} barn</em>), the adverb is a <strong>spotlight</strong> illuminating the <strong>action itself</strong> (<em>how the child eats</em>).",
    "adv_section1_label": "1. Adverbs of Manner (How does the child eat?)",
    "adv_card_langsomt_badge": "Manner (calm pace)",
    "adv_card_langsomt_desc": "The action is carried out calmly and without haste.",
    "adv_card_hurtigt_badge": "Manner (high speed)",
    "adv_card_hurtigt_desc": "The action takes place at a furious pace.",
    "adv_card_paent_badge": "Manner (proper style)",
    "adv_card_paent_desc": "The action follows table manners and etiquette.",
    "adv_card_graadigt_badge": "Manner (greedy appetite)",
    "adv_card_graadigt_desc": "The action is driven by intense, unstoppable hunger.",
    "adv_section2_label": "2. Attitude Adverbs & Central Adverbs (Sentence stance & time)",
    "adv_card_ikke_badge": "Negation (Central Adverb)",
    "adv_card_ikke_desc": "Reverses the entire action: The child does not eat at all!",
    "adv_card_gerne_badge": "Desire / Inclination (Central Adverb)",
    "adv_card_gerne_desc": "Shows willingness and a positive inclination toward the action.",
    "adv_card_nu_badge": "Time (Right now)",
    "adv_card_nu_desc": "Anchors the action precisely to this present second.",
    "adv_diff_title": "What is the difference between an adjective and an adverb?",
    "adv_diff_intro": "Many confuse adjectives and adverbs because they often look similar (e.g. <em>langsom</em> vs. <em>langsomt</em>). But cognitively, they point to two completely different things:",
    "adv_diff_box_adj_title": "🎨 Adjectives describe the THING",
    "adv_diff_box_adj_ex": "\"Et <strong>langsomt</strong> tog\" (A slow train)",
    "adv_diff_box_adj_note": "Answers: <em>Which</em> child / train? Declines by gender and definiteness (<em>stort</em> vs. <em>store</em>).",
    "adv_diff_box_adv_title": "🔦 Adverbs illuminate the ACTION",
    "adv_diff_box_adv_ex": "\"Toget kører <strong>langsomt</strong>\" (The train runs slowly)",
    "adv_diff_box_adv_note": "Answers: <em>How</em> does it run? Often receives a fixed <strong>-t</strong>, but <strong>NEVER</strong> declines by subject gender!",
    "adv_rule_chosen": "The chosen adverb:",
    "adv_action_next_title": "Ready for the final step: Connect sentences with Conjunctions",
    "adv_action_next_desc": "Bring the full sentence <strong>\"{sentence}\"</strong> onto the bridge and learn how connectors like <em>fordi</em>, <em>da</em>, <em>når</em>, and <em>selvom</em> create fluent text.",
    "adv_btn_next_conj": "Continue to Conjunctions ➔",
    "adv_ordstilling_title": "Position of the Central Adverb (5 parts)",
    "adv_ordstilling_desc": "Learn how central adverbs like 'ikke', 'gerne', and 'altid' are positioned in the sentence schema.",
    "adv_ordstilling_btn": "Go to Word Order (Part 2) ➔",
    "conj_hero_title": "Build a bridge between two sentences",
    "conj_hero_desc": "Conjunctions (connectors) are the cognitive bridge that links actions with reasons, times, and contrasts.",
