    "adj_hero_title": "Wie beschreiben wir ein Substantiv?",
    "adj_hero_desc": "Adjektive beleuchten das Substantiv und erzählen von seinen Eigenschaften, seinem Zustand und seinem Charakter.",
    "adj_choose_label": "Wähle ein Adjektiv, um das Kind zu beschreiben:",
    "adj_card_sulten_type": "Physiologischer Zustand",
    "adj_card_sulten_desc": "Das grundlegende Bedürfnis des Körpers nach Nahrung.",
    "adj_card_glad_type": "Emotionaler Zustand",
    "adj_card_glad_desc": "Positive mentale Energie.",
    "adj_card_lille_type": "Physische Dimension",
    "adj_card_lille_desc": "Körpergröße und Volumen.",
    "adj_card_hurtig_type": "Dynamisches Tempo",
    "adj_card_hurtig_desc": "Bewegung mit hoher Geschwindigkeit.",
    "adj_expl_box": "Das Adjektiv steht direkt vor dem Substantiv und malt ein bestimmtes Bild. Wenn wir das Adjektiv ändern, ändert sich der Zustand des Kindes – aber die Handlung selbst <em>({modalWord} spise)</em> bleibt dieselbe.",
    "adj_agreement_pill": "🧲 Kognitive Kongruenz",
    "adj_agreement_title": "Warum wird das Adjektiv gebeugt?",
    "adj_agreement_desc": "Das Adjektiv passt sich dem Substantiv wie ein Magnet an. Die Beugung hängt davon ab, ob die Bindung stark (bestimmt) oder schwach (unbestimmt) ist.",
    "adj_ctrl_form_legend": "1. Form & Stärke der Bindung:",
    "adj_ctrl_bestemt": "⚡ Bestimmt (Starke Bindung: immer -e)",
    "adj_ctrl_ubestemt": "⚪ Unbestimmt (Schwache Bindung: Genus entscheidet)",
    "adj_ctrl_noun_legend": "2. Substantiv & grammatisches Geschlecht:",
    "adj_ctrl_barn": "👶 Barn (et-Wort / Neutrum)",
    "adj_ctrl_bil": "🚗 Bil (en-Wort / Utrum)",
    "adj_ctrl_stem_legend": "3. Adjektivstamm:",
    "adj_status_strong": "⚡ <strong>STARKE BINDUNG:</strong> Der Magnet zieht mit maximaler Kraft! Die Endung wird unabhängig vom Geschlecht fest auf <strong>-e</strong> arretiert (<em>{phrase}</em>).",
    "adj_status_weak_et": "⚪ <strong>SCHWACHE BINDUNG:</strong> Lockerere Verbindung. Die Endung wird durch das Geschlecht des Substantivs bestimmt: Neutrum (et-Wort) verlangt <strong>-t</strong> (<em>{phrase}</em>).",
    "adj_status_weak_en": "⚪ <strong>SCHWACHE BINDUNG:</strong> Lockerere Verbindung. Die Endung wird durch das Geschlecht des Substantivs bestimmt: Utrum (en-Wort) erhält <strong>-ø</strong> (keine Endung) (<em>{phrase}</em>).",
    "adj_box_adj_label": "Adjektiv",
    "adj_box_noun_label": "Substantiv (Magnet)",
    "adj_badge_strong": "⚡ STARKE BINDUNG ⚡",
    "adj_badge_weak": "⚪ SCHWACHE BINDUNG ⚪",
    "adj_subrole_strong_barn": "Det barn (bestimmt)",
    "adj_subrole_strong_bil": "Den bil (bestimmt)",
    "adj_subrole_weak_barn": "Et barn (Neutrum)",
    "adj_subrole_weak_bil": "En bil (Utrum)",
    "adj_syntese_strong": "⚡ Starke Bindung (-e):",
    "adj_syntese_weak": "⚪ Schwache Bindung:",
    "adj_rule_strong": "<strong>Kognitive Regel bei starker Bindung:</strong> Wenn wir von einer <em>bestimmten</em> Sache sprechen („det store barn“, „den hurtige bil“), ist die Referenz bereits festgelegt. Daher verwendet das Dänische die feste Endung <strong>-e</strong> beim Adjektiv – unabhängig davon, ob das Wort Utrum oder Neutrum ist.",
    "adj_rule_weak": "<strong>Kognitive Regel bei schwacher Bindung:</strong> Wenn die Sache <em>unbestimmt</em> ist („et stort barn“, „en hurtig bil“), ist die Referenz offen. Hier muss das Adjektiv das grammatische Geschlecht des Substantivs widerspiegeln: <strong>-t</strong> für et-Wörter (Neutrum) und <strong>-ø</strong> (keine Endung) für en-Wörter (Utrum).",
    "adj_action_next_title": "Bereit für den nächsten Schritt: Adverbien hinzufügen",
