    "adj_expl_box": "El adjetivo se coloca directamente delante del sustantivo y pinta una imagen específica. Cuando cambiamos el adjetivo, el estado del niño cambia, pero la acción en sí <em>({modalWord} spise)</em> sigue siendo la misma.",
    "adj_agreement_pill": "🧲 Concordancia cognitiva",
    "adj_agreement_title": "¿Por qué se flexiona el adjetivo?",
    "adj_agreement_desc": "El adjetivo se adapta al sustantivo como un imán. La flexión depende de si la unión es fuerte (determinada) o débil (indeterminada).",
    "adj_ctrl_form_legend": "1. Forma y fuerza de la unión:",
    "adj_ctrl_bestemt": "⚡ Determinado (Unión fuerte: siempre -e)",
    "adj_ctrl_ubestemt": "⚪ Indeterminado (Unión débil: el género decide)",
    "adj_ctrl_noun_legend": "2. Sustantivo y género gramatical:",
    "adj_ctrl_barn": "👶 Barn (palabra con et / neutro)",
