    "adj_ctrl_stem_legend": "3. Raíz del adjetivo:",
    "adj_status_strong": "⚡ <strong>UNIÓN FUERTE:</strong> ¡El imán atrae con fuerza máxima! La terminación se fija en <strong>-e</strong> sin importar el género (<em>{phrase}</em>).",
    "adj_status_weak_et": "⚪ <strong>UNIÓN DÉBIL:</strong> Conexión más flexible. La terminación la determina el género del sustantivo: el neutro (palabra con et) lleva <strong>-t</strong> (<em>{phrase}</em>).",
    "adj_status_weak_en": "⚪ <strong>UNIÓN DÉBIL:</strong> Conexión más flexible. La terminación la determina el género del sustantivo: el género común (palabra con en) lleva <strong>-ø</strong> (sin terminación) (<em>{phrase}</em>).",
    "adj_box_adj_label": "Adjetivo",
    "adj_box_noun_label": "Sustantivo (Imán)",
    "adj_badge_strong": "⚡ UNIÓN FUERTE ⚡",
    "adj_badge_weak": "⚪ UNIÓN DÉBIL ⚪",
    "adj_subrole_strong_barn": "Det barn (determinado)",
    "adj_subrole_strong_bil": "Den bil (determinado)",
    "adj_subrole_weak_barn": "Et barn (neutro)",
    "adj_subrole_weak_bil": "En bil (género común)",
    "adj_syntese_strong": "⚡ Unión fuerte (-e):",
    "adj_syntese_weak": "⚪ Unión débil:",
    "adj_rule_strong": "<strong>Regla cognitiva en la unión fuerte:</strong> Cuando hablamos de una cosa <em>determinada</em> (\"det store barn\", \"den hurtige bil\"), la referencia ya está fijada. Por eso el danés usa la terminación fija <strong>-e</strong> en el adjetivo, independientemente de si la palabra es de género común o neutro.",
    "adj_rule_weak": "<strong>Regla cognitiva en la unión débil:</strong> Cuando la cosa es <em>indeterminada</em> (\"et stort barn\", \"en hurtig bil\"), la referencia queda abierta. Aquí el adjetivo debe reflejar el género gramatical del sustantivo: <strong>-t</strong> para palabras con et (neutro) y <strong>-ø</strong> (sin terminación) para palabras con en (género común).",
    "adj_action_next_title": "Listo para el siguiente paso: Añadir adverbios",
