    "adj_status_weak_en": "⚪ <strong>LIGAÇÃO FRACA:</strong> Conexão mais frouxa. A terminação é determinada pelo gênero do substantivo: gênero comum (palavra com en) recebe <strong>-ø</strong> (sem terminação) (<em>{phrase}</em>).",
