    "adj_syntese_weak": "⚪ Ligação fraca:",
    "adj_rule_strong": "<strong>Regra cognitiva na ligação forte:</strong> Quando nos referimos a algo <em>determinado</em> (\"det store barn\", \"den hurtige bil\"), a referência já está fixada. Portanto, o dinamarquês usa a terminação fixa <strong>-e</strong> no adjetivo – independentemente de a palavra ser de gênero comum ou neutro.",
    "adj_rule_weak": "<strong>Regra cognitiva na ligação fraca:</strong> Quando a coisa é <em>indeterminada</em> (\"et stort barn\", \"en hurtig bil\"), a referência fica aberta. Aqui o adjetivo deve refletir o gênero gramatical do substantivo: <strong>-t</strong> para palavras com et (neutro) e <strong>-ø</strong> (sem terminação) para palavras com en (gênero comum).",
