    "adj_status_strong": "⚡ <strong>强联结：</strong>磁铁发挥最大吸引力！无论何种词性，词尾均牢固锁定为 <strong>-e</strong>（<em>{phrase}</em>）。",
    "adj_status_weak_et": "⚪ <strong>弱联结：</strong>相对宽松的结合。词尾由名词的语法性别决定：中性（et-单词）加 <strong>-t</strong>（<em>{phrase}</em>）。",
    "adj_status_weak_en": "⚪ <strong>弱联结：</strong>相对宽松的结合。词尾由名词的语法性别决定：通性（en-单词）为 <strong>-ø</strong>（无词尾）（<em>{phrase}</em>）。",
    "adj_box_adj_label": "形容词",
    "adj_box_noun_label": "名词（磁铁）",
    "adj_badge_strong": "⚡ 强联结 ⚡",
    "adj_badge_weak": "⚪ 弱联结 ⚪",
    "adj_subrole_strong_barn": "Det barn（定指）",
    "adj_subrole_strong_bil": "Den bil（定指）",
    "adj_subrole_weak_barn": "Et barn（中性）",
    "adj_subrole_weak_bil": "En bil（通性）",
    "adj_syntese_strong": "⚡ 强联结 (-e)：",
    "adj_syntese_weak": "⚪ 弱联结：",
    "adj_rule_strong": "<strong>强联结的认知规则：</strong>当我们谈论一个<em>特定</em>事物时（\"det store barn\", \"den hurtige bil\"），指代对象已被锁定。因此，丹麦语形容词使用固定的词尾 <strong>-e</strong>——无论该名词是通性还是中性。",
    "adj_rule_weak": "<strong>弱联结的认知规则：</strong>当事物为<em>不定指</em>时（\"et stort barn\", \"en hurtig bil\"），指代是开放的。此时，形容词必须反映名词的语法性别：et-单词（中性）加 <strong>-t</strong>，en-单词（通性）为 <strong>-ø</strong>（不加词尾）。",
    "adj_action_next_title": "准备进入下一步：添加副词",
    "adj_action_next_desc": "带上句子 <strong>\"{sentence}\"</strong> 继续前进，了解副词如何描述孩子吃东西的方式。",
    "adj_btn_next_adv": "继续前往副词 ➔",
    "adj_ordstilling_title": "形容词与名词短语（第 4 部分）",
    "adj_ordstilling_desc": "了解形容词和扩展名词短语在句型图式中的摆放位置。",
    "adj_ordstilling_btn": "前往语序（第 4 部分）➔",
    "adv_hero_title": "我们如何修饰一个动作？",
    "adv_hero_subtitle": "形容词描绘的是<strong>事物</strong>（<em>det {adj} barn</em>），而副词则像一盏<strong>探照灯</strong>，聚焦照射在<strong>动作本身</strong>上（<em>孩子如何吃</em>）。",
    "adv_section1_label": "1. 方式副词（孩子怎么吃？）",
    "adv_card_langsomt_badge": "方式（从容平静的节奏）",
    "adv_card_langsomt_desc": "动作从容不迫、毫无匆忙地进行。",
    "adv_card_hurtigt_badge": "方式（高速度）",
    "adv_card_hurtigt_desc": "动作以极快的飞速进行。",
    "adv_card_paent_badge": "方式（得体文明的举止）",
    "adv_card_paent_desc": "动作遵循餐桌礼仪和规矩。",
    "adv_card_graadigt_badge": "方式（贪婪狼吞虎咽）",
    "adv_card_graadigt_desc": "动作由强烈而停不下来的饥饿所驱使。",
    "adv_section2_label": "2. 情态副词与中心副词（句子的态度与时间）",
    "adv_card_ikke_badge": "否定（中心副词）",
    "adv_card_ikke_desc": "彻底逆转整个动作：孩子根本不吃！",
    "adv_card_gerne_badge": "意愿 / 乐意（中心副词）",
    "adv_card_gerne_desc": "表现出对采取该动作的乐意与积极态度。",
    "adv_card_nu_badge": "时间（此时此刻）",
    "adv_card_nu_desc": "将动作精准固定在当下的这一瞬间。",
    "adv_diff_title": "形容词和副词有什么区别？",
    "adv_diff_intro": "许多人容易混淆形容词和副词，因为它们外观通常很相似（例如 <em>langsom</em> 与 <em>langsomt</em>）。但在认知层面上，它们指向两个截然不同的事物：",
    "adv_diff_box_adj_title": "🎨 形容词修饰【事物】",
    "adv_diff_box_adj_ex": "“Et <strong>langsomt</strong> tog”（慢速列车）",
    "adv_diff_box_adj_note": "回答：<em>哪一个</em>孩子 / 列车？根据词性与定指性发生变化（<em>stort</em> 对比 <em>store</em>）。",
    "adv_diff_box_adv_title": "🔦 副词照亮【动作】",
    "adv_diff_box_adv_ex": "“Toget kører <strong>langsomt</strong>”（火车开得很慢）",
    "adv_diff_box_adv_note": "回答：它<em>怎样</em>行驶？通常带有固定的 <strong>-t</strong>，但<strong>绝不</strong>随主语的性别发生变化！",
    "adv_rule_chosen": "选中的副词：",
    "adv_action_next_title": "准备进入最后一步：用连词连接句子",
    "adv_action_next_desc": "将完整句子 <strong>\"{sentence}\"</strong> 带到桥梁上，学习 <em>fordi</em>、<em>da</em>、<em>når</em> 和 <em>selvom</em> 等连词如何让表达连贯流畅。",
    "adv_btn_next_conj": "继续前往连词 ➔",
    "adv_ordstilling_title": "中心副词的位置（5 个成分）",
    "adv_ordstilling_desc": "了解像 'ikke'、'gerne' 和 'altid' 这样的中心副词在句型图式中的摆放位置。",
    "adv_ordstilling_btn": "前往语序（第 2 部分）➔",
    "conj_hero_title": "在两个句子之间搭起桥梁",
    "conj_hero_desc": "连词（连接词）是认知的桥梁，将动作与原因、时间及对比紧密连接起来。",
    "conj_cat_cause": "原因与结果",
    "conj_cat_time": "时间与时间定位",
    "conj_cat_contrast": "障碍与转折对比",
    "conj_cat_connect": "连接与目的",
    "conj_card_fordi_badge": "从属连词（从句）",
    "conj_card_fordi_role": "解释动作发生的原因或理由。",
    "conj_card_derfor_badge": "连接副词（倒装）",
    "conj_card_derfor_role": "表示该动作带来的逻辑结果或后果。",
    "conj_card_da_badge": "从属连词（过去的某一次）",
    "conj_card_da_role": "将动作与过去某个具体的、已结束的事件联系起来。",
    "conj_card_naar_badge": "从属连词（重复习惯 / 将来）",
    "conj_card_naar_role": "将动作与重复发生的习惯或未来的条件联系起来。",
    "conj_card_selvom_badge": "从属连词（让步从句）",
